## ✅ Simple Merge Sort Code in C (Without `malloc`, Beginner-Friendly)

```c
#include <stdio.h>

void merge(int arr[], int low, int mid, int high) {
    int temp[100];  // Enough size to handle most test cases
    int i = low;
    int j = mid + 1;
    int k = 0;

    // Merge the two halves
    while (i <= mid && j <= high) {
        if (arr[i] <= arr[j])
            temp[k++] = arr[i++];
        else
            temp[k++] = arr[j++];
    }

    // Copy remaining elements from left half
    while (i <= mid)
        temp[k++] = arr[i++];

    // Copy remaining elements from right half
    while (j <= high)
        temp[k++] = arr[j++];

    // Copy sorted elements back into original array
    for (i = low, k = 0; i <= high; i++, k++)
        arr[i] = temp[k];
}

void mergeSort(int arr[], int low, int high) {
    if (low < high) {
        int mid = (low + high) / 2;

        mergeSort(arr, low, mid);
        mergeSort(arr, mid + 1, high);

        merge(arr, low, mid, high);
    }
}

void printArray(int arr[], int size) {
    for (int i = 0; i < size; i++)
        printf("%d ", arr[i]);
    printf("\n");
}

int main() {
    int arr[] = {10, 7, 2, 8, 6, 4, 3};
    int n = sizeof(arr) / sizeof(arr[0]);

    printf("Original array: ");
    printArray(arr, n);

    mergeSort(arr, 0, n - 1);

    printf("Sorted array:   ");
    printArray(arr, n);

    return 0;
}
```

---

### 🧠 How it works (Real Simple Terms):

- **mergeSort** keeps dividing the array.
- **merge** takes two sorted parts and merges them into one.
- `temp[100]` is a fixed temporary array big enough to hold the merged result.

---

